ALTER POLICY advertisements_upload ON storage.objects WITH CHECK (bucket_id = 'tournament-advertisements' AND name ~ '^organizations/[0-9a-f-]{36}/logos/[0-9a-f-]{36}\.png$' AND (public.can_manage_organization(public.media_organization_id(name)) OR EXISTS (SELECT 1 FROM public.organization_members m WHERE m.organization_id = public.media_organization_id(name) AND m.user_id = auth.uid() AND m.role = 'TOURNAMENT_MANAGER')));